"1\"/><text x=\"261.61\" y=\"219.84\" font-family=\"'Noto Sans TC','Microsoft JhengHei',sans-serif\" font-size=\"14\" fill=\"#1f2430\" text-anchor=\"middle\" font-weight=\"700\">P1</text><circle cx=\"34\" cy=\"182.42\" r=\"3.5\" fill=\"#1f2430\" stroke=\"#1f2430\" stroke-width=\"1\"/><text x=\"20\" y=\"194.42\" font-family=\"'Noto Sans TC','Microsoft JhengHei',sans-serif\" font-size=\"14\" fill=\"#1f2430\" text-anchor=\"middle\" font-weight=\"700\">P2</text><text x=\"73.77\" y=\"301.37\" font-family=\"'Noto Sans TC','Microsoft JhengHei',sans-serif\" font-size=\"12\" fill=\"#6b7280\" text-anchor=\"middle\">正南</text></svg>",
